//! Trim re-bake slot (L07-J; G17).
//!
//! `fixtures/object-scene-producer-brush-slot/oracle.txt` was generated by
//! `tools/gen_slot_oracle.js` from baseline fbe4b8a3: the VERBATIM `bitmapTrimmedImage` and
//! `_hashSrc` (engine-bridge.js) run in a Node vm with recording stubs for the collaborators.
//! Row format:
//! `T scenario step anchor spec window trimMode bakeMode rect => kind rect key trims bakes
//! registers touches`; numbers are IEEE hex, the window is `start,end,offset` (`~` undefined,
//! `-` no window), kind is `U` undefined / `N` null / `V` value. Every scenario starts from
//! an empty cache. The replay drives the real `TrimSlots` over a real charged store; the
//! scripted provider only returns what the row's step configures and counts its calls.

use super::{
    anchor_key, slot_brush_id, window_key, BakeRefused, BakedInk, Resolution, SlotError,
    SlotRequest, SlotRules, TrimAnchor, TrimProvider, TrimSlots, TrimWindow, TrimmedPath,
};
use crate::evaluation::object_scene_style_kernels::bitmap_brush_resources_stamp::WorldRect;
use crate::evaluation::object_scene_style_kernels::bitmap_brush_resources_store::{
    BrushBitmapStore, BrushStoreError,
};
use crate::evaluation::property_follow_path_sample::SegmentIn;
use crate::revision::{ImageResourceBudget, ImageResourceError};
use std::sync::OnceLock;

const ORACLE: &str = include_str!("fixtures/object-scene-producer-brush-slot/oracle.txt");

pub(crate) struct Step {
    pub(crate) scenario: String,
    pub(crate) anchor: String,
    has_spec: bool,
    window: Option<TrimWindow>,
    trim: String,
    bake: String,
    rect: WorldRect,
    kind: String,
    result_rect: String,
    key: String,
    trims: usize,
    bakes: usize,
    registers: usize,
    touches: usize,
}

fn number(token: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(token, 16).expect("ieee hex"))
}

fn rect_of(token: &str) -> WorldRect {
    let n: Vec<f64> = token.split(',').map(number).collect();
    WorldRect {
        min_x: n[0],
        min_y: n[1],
        w: n[2],
        h: n[3],
    }
}

fn rect_hex(rect: &WorldRect) -> String {
    [rect.min_x, rect.min_y, rect.w, rect.h]
        .iter()
        .map(|v| format!("{:016x}", v.to_bits()))
        .collect::<Vec<_>>()
        .join(",")
}

pub(crate) fn steps() -> Vec<Step> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("T "))
        .map(|line| {
            let c: Vec<&str> = line.split_whitespace().collect();
            assert_eq!((c.len(), c[9]), (17, "=>"), "{line}");
            let window = (c[5] != "-").then(|| {
                let p: Vec<&str> = c[5].split(',').collect();
                TrimWindow {
                    start: number(p[0]),
                    end: number(p[1]),
                    // `win.offset || 0`: an undefined offset is the same as 0 for the key.
                    offset: if p[2] == "~" { 0.0 } else { number(p[2]) },
                }
            });
            Step {
                scenario: c[1].to_owned(),
                anchor: c[3].to_owned(),
                has_spec: c[4] == "1",
                window,
                trim: c[6].to_owned(),
                bake: c[7].to_owned(),
                rect: rect_of(c[8]),
                kind: c[10].to_owned(),
                result_rect: c[11].to_owned(),
                key: c[12].to_owned(),
                trims: c[13].parse().unwrap(),
                bakes: c[14].parse().unwrap(),
                registers: c[15].parse().unwrap(),
                touches: c[16].parse().unwrap(),
            }
        })
        .collect()
}

fn seg(k: f64) -> SegmentIn {
    SegmentIn {
        point: [k, k + 1.0],
        handle_in: Some([0.0, 0.0]),
        handle_out: Some([1.0, 0.0]),
    }
}

/// Returns what one oracle step configures; counts its calls.
pub(crate) struct Scripted {
    trim: String,
    bake: String,
    rect: WorldRect,
    tag: u8,
    pub(crate) trims: usize,
    pub(crate) bakes: usize,
    /// The anchor each `trimmed` call received.
    pub(crate) seen: Vec<TrimAnchor>,
}

impl Scripted {
    pub(crate) fn new(trim: &str, bake: &str, rect: WorldRect) -> Self {
        Self {
            trim: trim.to_owned(),
            bake: bake.to_owned(),
            rect,
            tag: 1,
            trims: 0,
            bakes: 0,
            seen: Vec::new(),
        }
    }

    /// Every baked pixel byte is `tag`, so a test can tell versions apart.
    pub(crate) fn tagged(mut self, tag: u8) -> Self {
        self.tag = tag;
        self
    }
}

impl TrimProvider for Scripted {
    fn trimmed(&mut self, anchor: &TrimAnchor, _: &TrimWindow) -> Option<TrimmedPath> {
        self.trims += 1;
        self.seen.push(anchor.clone());
        let segments = match self.trim.as_str() {
            "segs" => vec![seg(0.0), seg(1.0), seg(2.0)],
            "one" => vec![seg(0.0)],
            "empty" => vec![],
            "nosegs" | "nullret" => return None,
            other => panic!("trim mode {other}"),
        };
        Some(TrimmedPath {
            segments,
            closed: false,
        })
    }

    fn bake(&mut self, _: &TrimmedPath) -> Result<Option<BakedInk>, BakeRefused> {
        self.bakes += 1;
        if self.bake == "null" {
            return Ok(None);
        }
        Ok(Some(BakedInk {
            width: 2,
            height: 2,
            rgba: vec![self.tag; 16],
            rect: self.rect,
        }))
    }
}

pub(crate) fn big_store() -> BrushBitmapStore {
    BrushBitmapStore::with_budget(ImageResourceBudget::isolated(1 << 20).unwrap())
}

/// The anchor every oracle step trims: the same two-point centerline throughout.
pub(crate) fn base_anchor() -> &'static TrimAnchor {
    static ANCHOR: OnceLock<TrimAnchor> = OnceLock::new();
    ANCHOR.get_or_init(|| TrimAnchor {
        segments: vec![seg(0.0), seg(1.0)],
        closed: false,
    })
}

pub(crate) fn request<'a>(anchor: &'a str, window: Option<TrimWindow>) -> SlotRequest<'a> {
    SlotRequest {
        anchor_key: anchor,
        stroke_id: anchor,
        has_spec: true,
        window,
        anchor: base_anchor(),
        spec_bits: &[],
    }
}

/// Replay every oracle step; the ids of the steps that differ from the baseline.
pub(crate) fn replay(rules: SlotRules) -> Vec<String> {
    let mut bad = Vec::new();
    let mut scenario = String::new();
    let mut slots = TrimSlots::with_rules(rules);
    let mut store = big_store();
    for (at, step) in steps().iter().enumerate() {
        if step.scenario != scenario {
            scenario = step.scenario.clone();
            slots = TrimSlots::with_rules(rules);
            store = big_store();
        }
        let mut provider = Scripted::new(&step.trim, &step.bake, step.rect);
        let req = SlotRequest {
            has_spec: step.has_spec,
            ..request(&step.anchor, step.window)
        };
        let resolution = slots.resolve(&mut store, &req, &mut provider, None);
        let key = slots.key_of(&step.anchor).unwrap_or("-").to_owned();
        let (kind, rect, registers, touches) = match &resolution {
            Ok(Resolution::NoTrim) => ("U", "-".to_owned(), 0, 0),
            Ok(Resolution::Collapsed { .. }) => ("N", "-".to_owned(), 0, 0),
            Ok(Resolution::Ink { rect, reused, .. }) => (
                "V",
                rect_hex(rect),
                usize::from(!reused),
                usize::from(*reused),
            ),
            Err(_) => ("E", "-".to_owned(), 0, 0),
        };
        let ok = kind == step.kind
            && rect == step.result_rect
            && key == step.key
            && (provider.trims, provider.bakes) == (step.trims, step.bakes)
            && (registers, touches) == (step.registers, step.touches);
        if !ok {
            bad.push(format!("{}.{at}", step.scenario));
        }
    }
    bad
}

#[test]
fn oracle_header_and_counts_are_pinned() {
    let all = steps();
    assert_eq!(all.len(), 383);
    let count = |kind: &str| all.iter().filter(|s| s.kind == kind).count();
    assert_eq!((count("U"), count("N"), count("V")), (101, 159, 123));
    assert!(ORACLE.contains("(baseline fbe4b8a33e6d5a229f014154df2ba21988a9fabc)"));
    for sha in [
        "c5f94b8cc58236902624fc624b68cca633746e1fe89adf4dd0bc502acf7b44b2",
        "fa132f5b836247c092c06cd8e03abbf5e38e818298654949592dc6e44ab47c89",
    ] {
        assert!(ORACLE.contains(sha), "{sha}");
    }
    // The sweep exercised both cache hits that carry ink and hits that carry null.
    assert!(ORACLE.contains("hitV 14 hitN 4 fresh 264"));
}

#[test]
fn every_oracle_step_replays_identically_on_the_real_slot_and_store() {
    assert_eq!(replay(SlotRules::BASELINE), Vec::<String>::new());
}

#[test]
fn window_keys_are_math_round_of_tenths_with_the_offset_or_zero_rule() {
    let key = |s: f64, e: f64, o: f64| {
        window_key(
            "a",
            &TrimWindow {
                start: s,
                end: e,
                offset: o,
            },
        )
        .unwrap()
    };
    assert_eq!(key(10.0, 60.0, 0.0), "a|100|600|0");
    assert_eq!(key(10.04, 60.0, 0.0), "a|100|600|0");
    assert_eq!(key(10.05, 60.0, 0.0), "a|101|600|0");
    // Math.round ties toward +infinity: -1.5 -> -1 and -2.5 -> -2, not away from zero.
    assert_eq!(key(-0.15, -0.25, 0.0), "a|-1|-2|0");
    assert_eq!(key(0.25, 0.15, 0.0), "a|3|2|0");
    // `-0` and a NaN offset both print as 0.
    assert_eq!(key(0.0, 1.0, -0.0), "a|0|10|0");
    assert_eq!(key(0.0, 1.0, f64::NAN), "a|0|10|0");
    assert_eq!(key(-0.04, 1.0, 0.0), "a|0|10|0");
    assert_eq!(slot_brush_id("scene-root/L0/a"), "bmbtrim:scene-root/L0/a");
    assert_eq!(
        slot_brush_id(&anchor_key("doc-1", "scene-root", "L0", "a")),
        "bmbtrim:5:doc-1/10:scene-root/2:L0/1:a"
    );
}

#[test]
fn a_window_that_is_not_a_number_is_a_typed_refusal_that_touches_nothing() {
    let mut store = big_store();
    let mut slots = TrimSlots::new();
    for window in [
        TrimWindow {
            start: f64::NAN,
            end: 1.0,
            offset: 0.0,
        },
        TrimWindow {
            start: 0.0,
            end: f64::INFINITY,
            offset: 0.0,
        },
        TrimWindow {
            start: 0.0,
            end: 1.0,
            offset: f64::NEG_INFINITY,
        },
        TrimWindow {
            start: 1e300,
            end: 1.0,
            offset: 0.0,
        },
    ] {
        let mut provider = Scripted::new(
            "segs",
            "ok",
            WorldRect {
                min_x: 0.0,
                min_y: 0.0,
                w: 1.0,
                h: 1.0,
            },
        );
        let got = slots.resolve(&mut store, &request("a", Some(window)), &mut provider, None);
        assert!(matches!(got, Err(SlotError::WindowNotFinite)), "{window:?}");
        assert_eq!((provider.trims, provider.bakes, slots.len()), (0, 0, 0));
    }
    assert_eq!(store.stats().count, 0);
}

pub(crate) fn unit_rect() -> WorldRect {
    WorldRect {
        min_x: 1.0,
        min_y: 2.0,
        w: 3.0,
        h: 4.0,
    }
}

pub(crate) fn window(start: f64, end: f64) -> Option<TrimWindow> {
    Some(TrimWindow {
        start,
        end,
        offset: 0.0,
    })
}

#[test]
fn the_replacement_is_published_before_the_previous_version_is_released() {
    // Quota for exactly two 2x2 bitmaps: the old and the new version coexist while held.
    let budget = ImageResourceBudget::isolated(32).unwrap();
    let mut store = BrushBitmapStore::with_budget(budget.clone());
    let mut slots = TrimSlots::new();
    let mut a = Scripted::new("segs", "ok", unit_rect());
    let Ok(Resolution::Ink {
        bitmap: first,
        reused: false,
        ..
    }) = slots.resolve(&mut store, &request("a", window(0.0, 10.0)), &mut a, None)
    else {
        panic!("first bake must publish");
    };
    assert_eq!(
        (first.version(), first.id(), budget.used().unwrap()),
        (1, "bmbtrim:a", 16)
    );
    let mut b = Scripted::new("segs", "ok", unit_rect()).tagged(2);
    let Ok(Resolution::Ink {
        bitmap: second,
        reused: false,
        ..
    }) = slots.resolve(&mut store, &request("a", window(0.0, 20.0)), &mut b, None)
    else {
        panic!("second bake must publish");
    };
    // One slot id, one new version; the held old version is alive, charged and immutable.
    assert_eq!(
        (second.id(), second.version(), budget.used().unwrap()),
        ("bmbtrim:a", 2, 32)
    );
    assert_eq!(first.rgba8(), vec![1u8; 16].as_slice());
    assert_eq!(second.rgba8(), vec![2u8; 16].as_slice());
    assert!(store.is_current(&second) && !store.is_current(&first));
    assert_eq!(slots.len(), 1);
    drop(first);
    assert_eq!(budget.used().unwrap(), 16);
}

#[test]
fn a_replacement_that_does_not_fit_is_typed_and_keeps_the_previous_slot() {
    let budget = ImageResourceBudget::isolated(16).unwrap();
    let mut store = BrushBitmapStore::with_budget(budget.clone());
    let mut slots = TrimSlots::new();
    let mut a = Scripted::new("segs", "ok", unit_rect());
    let first = slots.resolve(&mut store, &request("a", window(0.0, 10.0)), &mut a, None);
    assert!(matches!(first, Ok(Resolution::Ink { reused: false, .. })));
    drop(first);
    let key_before = slots.key_of("a").map(str::to_owned);
    let mut b = Scripted::new("segs", "ok", unit_rect());
    let refused = slots.resolve(&mut store, &request("a", window(0.0, 20.0)), &mut b, None);
    assert!(matches!(
        refused,
        Err(SlotError::Store(BrushStoreError::Budget(
            ImageResourceError::Capacity
        )))
    ));
    // Nothing changed: same key, same charge, same resident version, and the old window still hits.
    assert_eq!(
        (slots.key_of("a").map(str::to_owned), budget.used().unwrap()),
        (key_before, 16)
    );
    let mut c = Scripted::new("segs", "ok", unit_rect());
    let hit = slots.resolve(&mut store, &request("a", window(0.0, 10.0)), &mut c, None);
    let Ok(Resolution::Ink {
        bitmap,
        reused: true,
        ..
    }) = hit
    else {
        panic!("the previous window must still hit");
    };
    assert_eq!((bitmap.version(), c.trims, c.bakes), (1, 0, 0));
}

#[test]
fn a_refused_bake_keeps_the_previous_key_so_the_next_resolve_retries() {
    struct Refusing;
    impl TrimProvider for Refusing {
        fn trimmed(&mut self, _: &TrimAnchor, _: &TrimWindow) -> Option<TrimmedPath> {
            Some(TrimmedPath {
                segments: vec![seg(0.0), seg(1.0)],
                closed: false,
            })
        }
        fn bake(&mut self, _: &TrimmedPath) -> Result<Option<BakedInk>, BakeRefused> {
            Err(BakeRefused("no canvas"))
        }
    }
    let mut store = big_store();
    let mut slots = TrimSlots::new();
    let got = slots.resolve(
        &mut store,
        &request("a", window(0.0, 5.0)),
        &mut Refusing,
        None,
    );
    assert!(matches!(
        got,
        Err(SlotError::Bake(BakeRefused("no canvas")))
    ));
    assert_eq!((slots.key_of("a"), store.stats().count), (None, 0));
    let mut good = Scripted::new("segs", "ok", unit_rect());
    let retry = slots.resolve(&mut store, &request("a", window(0.0, 5.0)), &mut good, None);
    assert!(matches!(retry, Ok(Resolution::Ink { reused: false, .. })));
    assert_eq!((good.trims, good.bakes), (1, 1));
}
